export function canShip(now: Date): boolean {
  const day = now.getDay();
  const hour = now.getHours();

  // Block weekends
  if (day === 0 || day === 6) {
    return false;
  }

  // Monday-Thursday: 9am-5pm
  if (day >= 1 && day <= 4) {
    return hour >= 9 && hour < 17;
  }

  // Friday: 9am-2pm (avoid late Friday deploys)
  if (day === 5) {
    return hour >= 9 && hour < 14;
  }

  return false;
}

